"""Return whether ``maybe_iter`` is an iterable, unless it's an instance of one
    of the base class, or tuple of base classes, given in ``unless``.
    """
def is_iterable(maybe_iter: object, unless: type | tuple[type, ...] = dict) -> bool {
    if isinstance(maybe_iter, str) {
        return False;
    }
    if isinstance(unless, tuple) {
        for cls in unless {
            if isinstance(maybe_iter, cls) {
                return False;
            }
        }
    } else {
        if isinstance(maybe_iter, unless) {
            return False;
        }
    }
    try {
        iter(maybe_iter);
        return True;
    } except TypeError {
        return False;
    }
}

"""Precondition: L[b:] is not empty.
    Return the index of the smallest value in L[b:]."""
def find_min(L: list[int], b: int) -> int {
    smallest = b;
    i = b + 1;
    while i < len(L) {
        if L[i] < L[smallest] {
            smallest = i;
        }
        i += 1;
    }
    return smallest;
}

