"""Helper function to parse atom strings given on the command line:
resid, resname/resid, chain/resname/resid, resname/resid/atom,
chain/resname/resid/atom, chain//resid, chain/resname/atom."""
def str2atom(a: str) -> tuple[str | None, str | None, int, str | None] {
    parts = a.split("/");
    match len(parts) {
        case 1:
            return (None, None, int(parts[0]), None);
        case 2:
            return (parts[0], parts[1], int(parts[1]), None);
        case 3:
            return (parts[0], parts[1], int(parts[2]), None);
        case 4:
            return (parts[0], parts[1], int(parts[2]), parts[3]);
        case 5:
            return (parts[0], parts[1], int(parts[2]), parts[3]);
        case 6:
            return (parts[0], parts[1], int(parts[2]), parts[3]);
        case _:
            raise ValueError("Invalid atom string.");
    }
}

